// Bild-URL inkl. Kurzzeit-Zugang aus dem Kamera-Attribut
const pfad = msg.data && msg.data.attributes && msg.data.attributes.entity_picture;
if (!pfad) {
    node.status({ fill: "red", shape: "ring", text: "kein entity_picture" });
    node.warn("Kein entity_picture an der Kamera gefunden – ist die Kamera online?");
    return null;
}
node.status({});
msg.method = "GET";
msg.url = "http://homeassistant:8123" + pfad; // ggf. anpassen, wenn Node-RED nicht als HA-Add-on läuft
msg.requestTimeout = 20000;
delete msg.payload;
return msg;

// ===== EINSTELLUNG: Adresse von Wasseruhr-CV =====
// Add-on: Hostname von der Info-Seite des Add-ons, sonst http://<IP>:8099
const CV_URL = "http://1938f1d6-wasseruhr-cv:8099";
// ====================================================================================

// Netzwerkfehler (Text statt HTTP-Status) meldet der HTTP-Node selbst an den Catch-Node
if (typeof msg.statusCode !== "number") return null;
if (msg.statusCode !== 200) {
    node.error(`Kamerabild nicht geladen (HTTP ${msg.statusCode})`, msg);
    return null;
}
if (!Buffer.isBuffer(msg.payload) || msg.payload.length < 1000) {
    node.error("Kamerabild ist leer oder kein Bild – HTTP-Node muss 'Binärer Buffer' liefern", msg);
    return null;
}
const basis = CV_URL.replace(/\/+$/, "");
// Neue Nachricht: Antwort-Header des Kamera-Abrufs dürfen nicht mitgeschickt werden
return {
    _msgid: msg._msgid,
    payload: msg.payload,
    method: "POST",
    url: basis + "/ablesen",
    headers: { "Content-Type": "image/jpeg" },
    requestTimeout: 20000,
    cv_url: basis,
    zaehler_ha: msg.zaehler_ha,
};

// Antwort von /ablesen prüfen. Nur sichere UND plausible Werte gehen an input_number.wasserzaehler.
//   Ausgang 1: msg.payload = neuer Zählerstand in m³ (Zahl) -> Action-Node
//   Ausgang 2: verworfen, msg.payload = Grund + Link zur Lernseite

// ===== EINSTELLUNGEN =====
const MAX_M3_PRO_STUNDE = 3;        // schnellerer Anstieg = Lesefehler
const TOLERANZ_M3 = 0.002;          // kleine Rückwärts-Abweichung (letzte Rolle dreht gerade) still ignorieren
const ALLE_ZIFFERN_GELERNT = true;  // erst schreiben, wenn für jede Ziffer 0–9 Vorlagen existieren
// =========================
const MIN_SCORE = 0.70, MIN_ABSTAND = 0.08;  // nur für die Anzeige unsicherer Rollen

// Netzwerkfehler (Text statt HTTP-Status) meldet der HTTP-Node selbst an den Catch-Node
if (typeof msg.statusCode !== "number") return [null, null];
const r = msg.payload;
const lernseite = (msg.cv_url || "") + "/";
msg.wasseruhr = r;

function verwerfen(grund, farbe) {
    node.status({ fill: farbe || "yellow", shape: "ring", text: grund.slice(0, 70) });
    msg.payload = `${grund} → nachlernen: ${lernseite}`;
    return [null, msg];
}
function unveraendert(bisher, jetzt) {
    flow.set("wucv_zeit", jetzt);
    node.status({ fill: "green", shape: "ring", text: `${bisher.toFixed(3)} m³ (unverändert)` });
    return [null, null];
}

if (msg.statusCode !== 200 || !r || typeof r !== "object") {
    return verwerfen(`CV-Dienst antwortet HTTP ${msg.statusCode}: ${r && r.detail ? r.detail : r}`, "red");
}
if (r.wert === null) {
    return verwerfen("Noch keine Vorlagen gelernt");
}
const wert = r.wert.toFixed(3);
if (!r.sicher) {
    const schwach = r.ziffern
        .filter(z => z.ziffer === null || z.score2 === null || z.score < MIN_SCORE || z.score - z.score2 < MIN_ABSTAND)
        .map(z => `R${z.rolle}=${z.ziffer} (${z.score}, 2.: ${z.zweitbeste} ${z.score2})`);
    return verwerfen(`unsicher ${wert} – ${schwach.join(", ")}`);
}
if (ALLE_ZIFFERN_GELERNT && r.fehlende_vorlagen.length > 0) {
    return verwerfen(`${wert} nicht übernommen – noch keine Vorlagen für Ziffer ${r.fehlende_vorlagen.join(", ")}`);
}

// Plausibilität gegen den aktuellen Wert von input_number.wasserzaehler:
// ein Wasserzähler zählt nur vorwärts und nur so schnell, wie Wasser fließen kann.
// Steht dort 0 (frisch angelegt) oder nichts Gültiges, wird der erste sichere Wert übernommen.
const ha = msg.zaehler_ha || {};
const bisher = parseFloat(ha.state);
const jetzt = Date.now();
if (Number.isFinite(bisher) && bisher > 0) {
    const diff = Math.round((r.wert - bisher) * 1000) / 1000;
    if (diff === 0) return unveraendert(bisher, jetzt);
    if (diff < 0) {
        if (-diff <= TOLERANZ_M3) return unveraendert(bisher, jetzt);
        return verwerfen(`${wert} ist kleiner als der Wert in Home Assistant (${bisher.toFixed(3)})`, "red");
    }
    const seit = flow.get("wucv_zeit") || Date.parse(ha.last_changed) || jetzt;
    const minuten = Math.max(0, (jetzt - seit) / 60000);
    if (diff > MAX_M3_PRO_STUNDE * minuten / 60 + TOLERANZ_M3) {
        return verwerfen(`${wert}: +${diff.toFixed(3)} m³ in ${Math.round(minuten)} min ist unplausibel`, "red");
    }
}
flow.set("wucv_zeit", jetzt);
node.status({ fill: "green", shape: "dot", text: `${wert} m³` });
msg.payload = r.wert;
return [msg, null];
